import * as THREE from './vendor/three.module.js';
import {CRITICAL_MASS as C} from './critical-mass.js?v=critical-mass-257';
export class CriticalMassFX {
 constructor(scene){this.root=new THREE.Group();scene.add(this.root);const mat=(color,opacity)=>new THREE.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false,blending:THREE.AdditiveBlending,toneMapped:false});this.ball=new THREE.Mesh(new THREE.IcosahedronGeometry(1,2),mat('#8ceeff',.65));this.halo=new THREE.Mesh(this.ball.geometry,mat('#3aaaff',.16));this.shock=new THREE.Mesh(new THREE.SphereGeometry(1,24,12),mat('#a8ffff',.28));this.ring=new THREE.Mesh(new THREE.TorusGeometry(1,.035,4,48),mat('#8cefff',.85));this.arcs=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,5,1,true),mat('#beffff',.9),160);this.arcs.frustumCulled=false;this.root.add(this.ball,this.halo,this.shock,this.ring,this.arcs);this.dummy=new THREE.Object3D();this.clear();}
 clear(){this.burstAge=10;this.burst=null;this.soundClock=0;this.warned=false;this.arcs.count=0;for(const m of[this.ball,this.halo,this.shock,this.ring])m.visible=false;}
 sound(audio,event='charge',progress=0){if(!audio||audio.state!=='running')return;try{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime,d=event==='charge'?.055:event==='warning'?.16:.28;o.type=event==='overload'?'sawtooth':'triangle';o.frequency.setValueAtTime(event==='overload'?140:220+progress*1050,t);o.frequency.exponentialRampToValueAtTime(event==='overload'?45:event==='burst'?110:400+progress*900,t+d);g.gain.setValueAtTime(event==='charge'?.014:.065,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(audio.destination);o.onended=()=>{o.disconnect();g.disconnect();};o.start();o.stop(t+d+.01);}catch{}}
 discharge(origin,power,hits=[],overload=false){this.burstAge=0;this.burst={origin:origin.clone(),level:power.level??1,radius:power.radius??C.radius,hits:hits.slice(0,12).map(h=>h.point.clone()),overload};}
 update(dt,time,{state,origin,left,right,audio=null}={}){this.burstAge+=dt;this.soundClock-=dt;this.arcs.count=0;const charging=state.charging,q=state.charge/C.maxCharge,critical=state.charge>=C.critical,col=critical?'#dfb5ff':'#9eefff';this.ball.visible=this.halo.visible=charging;this.shock.visible=this.ring.visible=false;const points=[];
  const arc=(a,b,seed,width)=>{let prev=a.clone();for(let i=1;i<=8;i++){const t=i/8,p=a.clone().lerp(b,t);if(i<8)p.add(new THREE.Vector3(Math.sin(seed+i*5+time*43),Math.cos(seed*3+i*7+time*39),Math.sin(i*8+time*47)).multiplyScalar(.04+q*.12));points.push({a:prev,b:p,width});prev=p;}};
  if(charging){const center=left.clone().lerp(right,.5),pulse=1+Math.sin(time*(critical?42:16))*(critical?.16:.06),size=(.07+q*.35)*pulse;this.ball.position.copy(center);this.halo.position.copy(center);this.ball.scale.setScalar(size);this.halo.scale.setScalar(size*1.8);this.ball.material.color.set(col);this.halo.material.color.set(critical?'#a84dff':'#227fff');for(let i=0;i<3+Math.floor(q*5);i++){const a=time*6+i*2.399,r=.15+q*.5,p=center.clone().add(new THREE.Vector3(Math.cos(a)*r,Math.sin(a*1.5)*r,Math.sin(a)*r));arc(i%2?left:right,p,i,.012+q*.016);}if(this.soundClock<=0){this.sound(audio,'charge',q);this.soundClock=critical?.055:state.charge>=C.powerful?.09:.2;}if(critical&&!this.warned){this.sound(audio,'warning',1);this.warned=true;}}else this.warned=false;
  if(this.burst&&this.burstAge<.65){const b=this.burst,t=this.burstAge/.65,r=b.radius*Math.min(1,t*3.5),color=b.overload?'#f493ff':'#b9ffff';this.shock.visible=this.ring.visible=true;this.shock.position.copy(b.origin);this.shock.scale.setScalar(Math.max(.02,r));this.shock.material.color.set(color);this.shock.material.opacity=(1-t)*(.12+.15*b.level);this.ring.position.copy(b.origin);this.ring.rotation.x=Math.PI/2;this.ring.scale.setScalar(Math.max(.02,r));this.ring.material.color.set(color);this.ring.material.opacity=(1-t)*.8;if(t<.17){this.ball.visible=true;this.ball.position.copy(b.origin);this.ball.scale.setScalar(.35+b.level*.6);this.ball.material.color.set(color);}for(let i=0;i<8;i++){const a=i*Math.PI/4,p=b.origin.clone().add(new THREE.Vector3(Math.sin(a)*r,Math.sin(a*2+time*15)*r*.45,Math.cos(a)*r));arc(b.origin,p,i,.02*(1-t));}if(t<.5)for(let i=0;i<b.hits.length;i++)arc(b.origin,b.hits[i],20+i,.035*(1-t));}
  let n=0;for(const p of points){if(n>=160)break;const d=p.b.clone().sub(p.a);this.dummy.position.copy(p.a).add(p.b).multiplyScalar(.5);this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());this.dummy.scale.set(p.width,d.length(),p.width);this.dummy.updateMatrix();this.arcs.setMatrixAt(n++,this.dummy.matrix);}this.arcs.count=n;this.arcs.material.color.set(critical?'#edcaff':'#c7ffff');this.arcs.instanceMatrix.needsUpdate=true;
 }
 diagnostics(){return{arcs:this.arcs.count,charging:this.halo.visible,shock:this.shock.visible,burstAge:this.burstAge};}
}
